contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositEtherAmount is the ETH to forward to c when calling deposit
    // tokenIds are arbitrary NFT ids to deposit; caller (this contract) must own them — but in the checker setup
    // the test harness deploys a fresh C and will not have NFTs; to make the call a no-op for transfers the
    // test only asserts behaviour when baseToken==address(0). We will only require that c.baseToken() == address(0)
    // as a precondition so that ETH path is used. The general rule: after deposit called with baseTokenAmount and value,
    // address(c).balance increases by exactly baseTokenAmount (and msg.value leftover refunded to sender), and virtual reserves unchanged.

    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, uint256 depositEtherAmount) public payable {
        require(true);

        // Precondition: the pool must be initialized to use ETH as base token. Observe via public getter.
        address base = c.baseToken();

        // Read observable before-values
        uint256 beforeBalance = address(c).balance;
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();

        // If base token is nonzero, we skip making the state-changing deposit call and assert vacuously
        // (the assert must still be a non-trivial relation). So we attempt the deposit only when base==address(0).
        bool didRevert = false;
        if (base == address(0)) {
            // ensure this contract has enough balance to forward depositEtherAmount
            // The test runner will fund the caller if needed; require ensures safety
            require(address(this).balance >= depositEtherAmount, "insufficient test balance");

            try c.deposit{value: depositEtherAmount}(tokenIds, baseTokenAmount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        // Read after-values
        uint256 afterBalance = address(c).balance;
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();

        // General property to assert (only meaningful when base==address(0) and call did not revert):
        // - virtual reserves unchanged
        // - contract balance increased by exactly baseTokenAmount when deposit succeeded
        // If deposit reverted or base!=0, we assert that virtual reserves did not increase (they must be <= or ==)
        // We express a single assert combining cases.
        assert(
            // Case A: base==0 and call succeeded => exact increase equal to baseTokenAmount and virtual reserves unchanged
            (base == address(0) && !didRevert && afterBalance == beforeBalance + baseTokenAmount && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft)
            // Case B: base==0 and call reverted => virtual reserves unchanged and balance unchanged
            || (base == address(0) && didRevert && afterBalance == beforeBalance && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft)
            // Case C: base!=0 => we didn't perform the ETH path; require that invoking deposit via ETH wasn't attempted so observable virtual reserves stayed the same
            || (base != address(0) && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // tokenIds: NFT ids to deposit (may be empty)
    // baseTokenAmount: declared base token amount parameter for deposit
    // depositEtherAmount: ETH forwarded when calling deposit (must be provided from this contract balance)
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, uint256 depositEtherAmount) public payable {
        require(true);

        // Observe pre-call public state
        address base = c.baseToken();
        uint256 beforeBalance = address(c).balance;
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();

        // We will either call deposit (if base==address(0)) or skip calling it (if base!=0).
        // The state-changing call must be a top-level statement. Prepare to ensure this contract has ETH if needed.
        if (base == address(0)) {
            require(address(this).balance >= depositEtherAmount, "insufficient test balance");
            // Perform the deposit as a top-level state-changing call; capture whether it reverts using try/catch.
            bool didRevert;
            try c.deposit{value: depositEtherAmount}(tokenIds, baseTokenAmount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }

            // Observe post-call public state
            uint256 afterBalance = address(c).balance;
            uint128 afterVirtualBase = c.virtualBaseTokenReserves();
            uint128 afterVirtualNft = c.virtualNftReserves();

            // Assert the general invariant for ETH-path pools: either success with exact balance increase and unchanged virtuals,
            // or revert leaving balance and virtuals unchanged.
            assert(
                (!didRevert && afterBalance == beforeBalance + baseTokenAmount && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft)
                || (didRevert && afterBalance == beforeBalance && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft)
            );
            return;
        }

        // If pool does not use ETH, we do not call deposit and simply assert virtual reserves unchanged.
        uint128 afterVirtualBaseNoCall = c.virtualBaseTokenReserves();
        uint128 afterVirtualNftNoCall = c.virtualNftReserves();
        assert(afterVirtualBaseNoCall == beforeVirtualBase && afterVirtualNftNoCall == beforeVirtualNft);
    }

    receive() external payable {}
}

