contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call buy with parameters. To allow paying ETH when baseToken == address(0), we accept an etherAmount param
    // and forward it when calling c.buy. The function is payable to allow the checker to fund this contract.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofProof, bool[] calldata proofFlags, uint256 etherAmount) public payable {
        require(address(this).balance >= etherAmount, "not enough balance to forward");

        // Build MerkleMultiProof struct in memory
        C.MerkleMultiProof memory proof;
        proof.proof = proofProof;
        proof.flags = proofFlags;

        // Read before-values
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 beforeVirtualNft = c.virtualNftReserves();
        uint256 factoryProtocolFeeRate = Factory(c.factory()).protocolFeeRate();

        // Perform call and catch revert
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // We must call as msg.sender being this contract; use try/catch to detect revert
        try c.buy{value: etherAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterVirtualNft = c.virtualNftReserves();

        // If the call reverted, virtual reserves must be unchanged
        // If it succeeded, virtualBaseTokenReserves must have increased by at least (netInputAmount - feeAmount - protocolFeeAmount)
        // and virtualNftReserves must have decreased by sum of tokenWeights (observed via difference). However we cannot directly get sum inside assert, so we express relation between before/after using netInputAmount and fees which are returned by buy.

        // Final assertion: either reverted and reserves unchanged, or succeeded and afterVirtualBase >= beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount)
        assert(
            (reverted && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft)
            || (!reverted && afterVirtualBase >= beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with all logic
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags,
        uint256 stolenProofsLen
    ) public payable {
        // build MerkleMultiProof in memory
        C.MerkleMultiProof memory proof;
        proof.proof = proofProof;
        proof.flags = proofFlags;

        // read before-values (views only)
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 beforeVirtualNft = c.virtualNftReserves();

        // prepare an empty array for stolenNftProofs (length parameter to vary calldata size)
        IStolenNftOracle.Message[] memory stolenProofs = new IStolenNftOracle.Message[](stolenProofsLen);

        // perform the state-changing call at top-level and capture revert via try/catch
        bool reverted;
        uint256 netOutputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        try c.sell(tokenIds, tokenWeights, proof, stolenProofs) returns (uint256 net, uint256 fee, uint256 proto) {
            reverted = false;
            netOutputAmount = net;
            feeAmount = fee;
            protocolFeeAmount = proto;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterVirtualNft = c.virtualNftReserves();

        // compute sum of tokenWeights in a way allowed in assert: compute now in memory
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // General invariant: if reverted -> reserves unchanged; else -> virtualNftReserves increased by sumWeights
        // and virtualBaseTokenReserves decreased by at least netOutputAmount + feeAmount + protocolFeeAmount
        assert(
            (reverted && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft)
            || (!reverted
                && afterVirtualNft == beforeVirtualNft + sumWeights
                && beforeVirtualBase >= afterVirtualBase
                && (beforeVirtualBase - afterVirtualBase) >= (netOutputAmount + feeAmount + protocolFeeAmount)
            )
        );
    }

    // allow receiving ETH if needed by c in other tests
    receive() external payable {}
}

