contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We check behavior of buy: if it doesn't revert then (1) c.initialized must be true,
    // (2) virtualNftReserves_after = virtualNftReserves_before - weightSum, where weightSum is
    // computed by calling c.sumWeightsAndValidateProof on the provided arrays and proof,
    // and (3) virtualBaseTokenReserves adjusted as per function (we only check monotonic change: it increases by >=0 when buy succeeds).

    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        C.MerkleMultiProof calldata proof
    ) public payable {
        // No precondition on inputs; we will attempt to call buy and observe whether it reverts.

        // Observe pre-state via public getters
        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        uint128 beforeVirtualBaseTokenReserves = c.virtualBaseTokenReserves();
        bool beforeInitialized = c.initialized();

        // compute expected weight sum using the contract's public helper
        uint256 weightSum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof);
        // The call above could revert (if proof invalid). To follow constraints, we treat that as part of control flow
        // but sumWeightsAndValidateProof is view; it will revert on invalid proof. So wrap the buy call attempt separately.

        bool buyReverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // Attempt the buy call; supply msg.value as 0 here (run is payable but we don't forward ether)
        try c.buy{value: 0}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            buyReverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            buyReverted = true;
        }

        // Read post-state
        uint128 afterVirtualNftReserves = c.virtualNftReserves();
        uint128 afterVirtualBaseTokenReserves = c.virtualBaseTokenReserves();
        bool afterInitialized = c.initialized();

        // If buy did not revert then:
        // - contract must have been initialized (initialize() requires being called before buy normally),
        // - virtualNftReserves must have decreased by exactly weightSum,
        // - virtualBaseTokenReserves must have increased by at least 0 (i.e., not decreased).
        // Otherwise (if reverted) we assert nothing about those numeric relations.

        assert(
            buyReverted || (
                afterInitialized == true
                && afterVirtualNftReserves + weightSum == beforeVirtualNftReserves
                && uint256(afterVirtualBaseTokenReserves) >= uint256(beforeVirtualBaseTokenReserves)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Single simple property: when buy(...) does NOT revert, virtualNftReserves_after = virtualNftReserves_before - weightSum
    // We require tokenIds and tokenWeights arrays length > 0 and equal, and the call is made with zero ETH forwarded.
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        C.MerkleMultiProof calldata proof
    ) public payable {
        require(tokenIds.length > 0 && tokenIds.length == tokenWeights.length, "bad inputs");

        // observe before
        uint128 beforeVn = c.virtualNftReserves();

        // compute weight sum via the public view (this may revert on invalid proof; that's fine)
        uint256 weightSum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof);

        bool reverted;
        uint256 retNet;
        uint256 retFee;
        uint256 retProtocol;

        // attempt to call buy with no ETH forwarded
        try c.buy{value: 0}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            retNet = n; retFee = f; retProtocol = p;
        } catch {
            reverted = true;
        }

        uint128 afterVn = c.virtualNftReserves();

        // If buy did not revert then virtualNftReserves must have decreased by exactly weightSum.
        // expressed as: reverted OR (beforeVn == afterVn + weightSum)
        assert(reverted || uint256(beforeVn) == uint256(afterVn) + weightSum);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Parameters: tokenIds and tokenWeights must be non-empty and same length; stolenNftProofs may be empty.
    // We call sell without sending ETH (sell is non-payable) and check that if it does not revert,
    // then virtualBaseTokenReserves_after = virtualBaseTokenReserves_before - (netOutput + fee + protocolFee)
    // which is the intended update in sell().
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        C.MerkleMultiProof calldata proof,
        IStolenNftOracle.Message[] calldata stolenNftProofs
    ) public payable {
        require(tokenIds.length > 0 && tokenIds.length == tokenWeights.length, "bad inputs");

        // observe before value
        uint128 beforeVb = c.virtualBaseTokenReserves();

        // call sumWeightsAndValidateProof to ensure inputs are consistent with merkle proof (may revert)
        uint256 weightSum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof);

        bool reverted = false;
        uint256 netOut;
        uint256 fee;
        uint256 protocol;

        try c.sell(tokenIds, tokenWeights, proof, stolenNftProofs) returns (uint256 n, uint256 f, uint256 p) {
            netOut = n; fee = f; protocol = p;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterVb = c.virtualBaseTokenReserves();

        // If sell did not revert then the contract subtracts (netOutput + fee + protocolFee) from virtualBaseTokenReserves.
        // Expressed as: reverted OR beforeVb == afterVb + (netOut + fee + protocol)
        assert(reverted || uint256(beforeVb) == uint256(afterVb) + (netOut + fee + protocol));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We require small fixed bounds to help the prover: both arrays non-empty and lengths <= 4
    function run(
        uint256[] calldata inputTokenIds,
        uint256[] calldata inputTokenWeights,
        C.MerkleMultiProof calldata inputProof,
        IStolenNftOracle.Message[] calldata stolenNftProofs,
        uint256[] calldata outputTokenIds,
        uint256[] calldata outputTokenWeights,
        C.MerkleMultiProof calldata outputProof,
        uint256 ethAmount
    ) public payable {
        require(inputTokenIds.length > 0 && inputTokenIds.length == inputTokenWeights.length, "bad input len");
        require(outputTokenIds.length > 0 && outputTokenIds.length == outputTokenWeights.length, "bad output len");
        require(inputTokenIds.length <= 4 && outputTokenIds.length <= 4, "too many");

        // observe before value
        uint128 beforeVn = c.virtualNftReserves();

        // Call change; send ETH if baseToken is address(0). We must ensure contract has funds to forward if needed.
        // To simplify, pass ethAmount and require this test has that balance when sending.
        if (ethAmount > 0) {
            require(address(this).balance >= ethAmount, "no funds");
        }

        bool reverted;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.change{value: ethAmount}(
            inputTokenIds,
            inputTokenWeights,
            inputProof,
            stolenNftProofs,
            outputTokenIds,
            outputTokenWeights,
            outputProof
        ) returns (uint256 f, uint256 p) {
            feeAmount = f;
            protocolFeeAmount = p;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterVn = c.virtualNftReserves();

        // compute sums by calling the pool's sumWeightsAndValidateProof (view) to match pool logic
        uint256 inputSum = c.sumWeightsAndValidateProof(inputTokenIds, inputTokenWeights, inputProof);
        uint256 outputSum = c.sumWeightsAndValidateProof(outputTokenIds, outputTokenWeights, outputProof);

        // If call did not revert then virtualNftReserves must have increased by (inputSum - outputSum).
        // That is: afterVn == beforeVn + (inputSum - outputSum)
        // To avoid underflow in assert, compare as uint256.
        assert(reverted || uint256(afterVn) == uint256(beforeVn) + (inputSum - outputSum));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test deposit: small bounds to help solver
    function run(
        uint256[] calldata tokenIds,
        uint256 baseTokenAmount,
        uint256 ethAmount
    ) public payable {
        require(tokenIds.length > 0 && tokenIds.length <= 4, "bad tokenIds len");

        // We will send ETH only when desired and ensure this contract has funds
        if (ethAmount > 0) require(address(this).balance >= ethAmount, "no funds");

        // Observe before values: pool NFT balance for its nft() and pool monetary balance
        address poolNft = c.nft();
        address poolBaseToken = c.baseToken();

        uint256 beforeNftBalance = ERC721(poolNft).balanceOf(address(c));
        uint256 beforePoolBalance = (poolBaseToken == address(0)) ? address(c).balance : ERC20(poolBaseToken).balanceOf(address(c));

        // attempt deposit; capture whether it reverted
        bool reverted;
        try c.deposit{value: ethAmount}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterNftBalance = ERC721(poolNft).balanceOf(address(c));
        uint256 afterPoolBalance = (poolBaseToken == address(0)) ? address(c).balance : ERC20(poolBaseToken).balanceOf(address(c));

        // If deposit succeeded then pool's NFT balance must increase by exactly tokenIds.length
        // and pool's token/ETH balance must increase by baseTokenAmount (or ethAmount if baseToken==0).
        // If deposit reverted then neither observable balance should have increased.
        if (!reverted) {
            assert(afterNftBalance == beforeNftBalance + tokenIds.length &&
                   (poolBaseToken == address(0) ? afterPoolBalance == beforePoolBalance + ethAmount : afterPoolBalance == beforePoolBalance + baseTokenAmount));
        } else {
            assert(afterNftBalance == beforeNftBalance && afterPoolBalance == beforePoolBalance);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take tokenIds length and weightSum via arrays, and provide a MerkleMultiProof encoded as bytes arrays
    // For simplicity, supply empty proofs to exercise merkleRoot == 0 branch as well as non-zero root may revert.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofProof, bool[] calldata proofFlags, uint256 ethAmount) public payable {
        // Ensure we have the Ether available if caller wants to forward it to c.buy
        if (ethAmount > 0) {
            require(address(this).balance >= ethAmount, "no-eth");
        }

        // Read reserves before
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 beforeVirtualNft = c.virtualNftReserves();

        // Prepare MerkleMultiProof struct in memory
        C.MerkleMultiProof memory proof = C.MerkleMultiProof({proof: new bytes32[](proofProof.length), flags: new bool[](proofFlags.length)});
        for (uint256 i = 0; i < proofProof.length; i++) proof.proof[i] = proofProof[i];
        for (uint256 i = 0; i < proofFlags.length; i++) proof.flags[i] = proofFlags[i];

        // Attempt the buy call, capturing revert
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // We must call c.buy as top-level statement when it mutates state. Use try/catch to detect revert.
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 _net, uint256 _fee, uint256 _protocol) {
            reverted = false;
            netInputAmount = _net;
            feeAmount = _fee;
            protocolFeeAmount = _protocol;
        } catch {
            reverted = true;
        }

        // Read reserves after
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterVirtualNft = c.virtualNftReserves();

        // Compute weight sum as sum of tokenWeights (safe: loops bounded by calldata length)
        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }

        // If the call reverted, then either the ETH/ERC20 amount conditions or merkle proof or other checks failed.
        // If it did not revert, then the function's body updates virtualBaseTokenReserves by (netInputAmount - feeAmount - protocolFeeAmount)
        // and virtualNftReserves decreases by weightSum. We assert exactly that relation when not reverted.
        assert(
            reverted || (
                afterVirtualBase == beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount) &&
                // avoid underflow by using >= check on beforeVirtualNft
                beforeVirtualNft >= weightSum &&
                afterVirtualNft == beforeVirtualNft - weightSum
            )
        );
    }

    receive() external payable {}
}
